import { calendarDay, publicProfileUrl, publicSourceLabel, validatePublicSnapshot, validateSocialMeasurement, type PublicNetwork, type SocialAccount } from './socialMetrics';

export const monthlyMetrics = { followers: 'Seguidores', views: 'Visualizaciones', reach: 'Alcance' } as const;
export type MonthlyMetric = keyof typeof monthlyMetrics;
export interface MonthlyPoint { month: string; start: string; end: string; value: number | null; evidence?: string; capturedAt?: string; source?: string }

/** Identifiers generated by the removed AI Studio seeds, never observations. Keep stored originals untouched. */
export function isUnverifiedSeed(id: string) {
  return /^m-(ig|fb|tt)-(sep|ago|oct)-/.test(id) || /^snap-(nh-ig-|c[12]-ig-|own-ig-sep$)/.test(id);
}
export function hasUnverifiedSeeds(account: SocialAccount) {
  return account.measurements.some(m => isUnverifiedSeed(m.id)) || !!account.publicProfiles?.some(p => p.snapshots.some(s => isUnverifiedSeed(s.id)));
}
export function monthWindows(start: string, end: string, today = new Date().toISOString().slice(0, 10)) {
  if (!calendarDay(start) || !calendarDay(end) || start > end || end > today) throw new Error('Elegí fechas válidas, hasta hoy.');
  const windows: {month: string; start: string; end: string}[] = [];
  let cursor = `${start.slice(0, 7)}-01`;
  while (cursor <= end) {
    if (windows.length >= 60) throw new Error('Consultá hasta cinco años por vez.');
    const next = new Date(`${cursor}T00:00:00Z`); next.setUTCMonth(next.getUTCMonth() + 1);
    const nextDay = next.toISOString().slice(0, 10);
    const last = new Date(Date.parse(`${nextDay}T00:00:00Z`) - 86400000).toISOString().slice(0, 10);
    windows.push({ month: cursor.slice(0, 7), start: cursor < start ? start : cursor, end: last > end ? end : last });
    cursor = nextDay;
  }
  return windows;
}
export function monthlySeries(account: SocialAccount | undefined, network: PublicNetwork, metric: MonthlyMetric, start: string, end: string, today?: string): MonthlyPoint[] {
  return monthWindows(start, end, today).map(window => {
    const empty: MonthlyPoint = { ...window, value: null };
    if (!account || account.network !== network || account.presence?.status === 'not-used') return empty;
    let canonical: string;
    try { canonical = publicProfileUrl(network, account.profileUrl); } catch { return empty; }
    const candidates: {value: number; evidence: string; capturedAt: string; source: string}[] = [];
    for (const m of account.measurements) {
      try {
        validateSocialMeasurement(m);
        if (isUnverifiedSeed(m.id) || m.network !== network || publicProfileUrl(network, m.profileUrl) !== canonical || (account.accountId && m.accountId !== account.accountId) || m.capturedAt.slice(0,10) > (today || new Date().toISOString().slice(0,10))) continue;
        // Followers are a dated stock. Period metrics must cover precisely this window, never a partial sample.
        if (metric === 'followers' ? m.capturedAt.slice(0,10) < window.start || m.capturedAt.slice(0,10) > window.end : m.periodStart !== window.start || m.periodEnd !== window.end) continue;
        const value = m.metrics[metric];
        if (typeof value === 'number') candidates.push({ value, evidence: m.evidence, capturedAt: m.capturedAt, source: m.source === 'official-api' ? 'API oficial' : 'Informe cargado manualmente' });
      } catch { /* Invalid records do not become a bar. */ }
    }
    if (metric === 'followers') {
      for (const p of account.publicProfiles || []) {
        if (p.role !== 'own' || !p.confirmed) continue;
        try { if (publicProfileUrl(network, p.profileUrl) !== canonical) continue; } catch { continue; }
        for (const s of p.snapshots) {
          try {
            validatePublicSnapshot(network, s);
            if (isUnverifiedSeed(s.id) || publicProfileUrl(network, s.profileUrl) !== canonical || s.capturedAt.slice(0,10) < window.start || s.capturedAt.slice(0,10) > window.end || s.followers === undefined) continue;
            candidates.push({ value: s.followers, evidence: s.evidence, capturedAt: s.capturedAt, source: publicSourceLabel(s.source) });
          } catch { /* No synthetic history or inferred totals. */ }
        }
      }
    }
    const selected = candidates.sort((a,b) => Date.parse(b.capturedAt) - Date.parse(a.capturedAt))[0];
    return selected ? { ...window, ...selected } : empty;
  });
}
